import { useVaultStore } from '../stores/vault.store';
import { useDeviceRegistryStore } from '../stores/device-registry.store';
import { clearAllUserStores } from '../lib/clear-user-stores';
import {
  initializeVault,
  encryptVaultKeys,
  decryptVaultKeys,
  deriveIpnsName,
  hexToBytes,
  bytesToHex,
} from '@cipherbox/crypto';
import { getOrCreateDeviceIdentity } from '../lib/device/identity';
import { detectDeviceInfo } from '../lib/device/info';
import { initializeOrSyncRegistry } from '../services/device-registry.service';
import { initializeBin } from '../services/bin.service';
import { useBinStore } from '../stores/bin.store';
import { vaultControllerGetConfig } from '../api/vault/vault';

export function useAuth() {
  const navigate = useNavigate();
  const {
    isLoggedIn: coreKitLoggedIn,
    isInitialized: coreKitInitialized,
    isRequiredShare,
    loginWithGoogle: coreKitLoginGoogle,
    loginWithEmailOtp: coreKitLoginEmail,
    loginWithWallet: coreKitLoginWallet,
    getVaultKeypair,
    getPublicKeyHex,
    logout: coreKitLogout,
  } = useCoreKitAuth();
  const { syncStatus } = useCoreKit();
  const {
    accessToken,
    isAuthenticated,
    lastAuthMethod,
    userEmail,
    setAccessToken,
    setLastAuthMethod,
    setUserEmail,
    setVaultKeypair,
  } = useAuthStore();

  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const restoringRef = useRef(false);

  // Stable refs for functions used in the session restoration effect.
  // This prevents the effect from re-firing when function references change.
  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);

  // Pending auth state for REQUIRED_SHARE flow.
  // Stored in Zustand (not useState) so the state is shared across all
  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
  // via its own useAuth() call.
  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);

  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;

  // Get vault store actions
  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);

  /**
   * Initialize vault for new users or load existing vault keys.
   * Called after successful backend authentication.
   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
   */
  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
    // Get user's secp256k1 keypair from Core Kit TSS export
    const userKeypair = await getVaultKeypair();

    if (!userKeypair) {
      throw new Error('Failed to get vault keypair from Core Kit');
    }

    // Store keypair in auth store for crypto operations
    setVaultKeypair(userKeypair);

    try {
      // Try to fetch existing vault
      const existingVault = await vaultApi.getVault();

      // Store TEE keys if available
      if (existingVault.teeKeys) {
        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
      }

      // Vault exists - decrypt keys and load into store
      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
      const decryptedVault = await decryptVaultKeys(
        {
          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
        },
        userKeypair.privateKey
      );

      setVaultKeys({
        rootFolderKey: decryptedVault.rootFolderKey,
        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
        rootIpnsName: existingVault.rootIpnsName,
        vaultId: existingVault.id,
      });
    } catch (error) {
      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;

      if (is404) {
        // New user - initialize vault
        console.log(
          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
        );
        const newVault = await initializeVault(userKeypair.privateKey);
        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);

        const storedVault = await vaultApi.initVault({
          ownerPublicKey: bytesToHex(userKeypair.publicKey),
          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
          rootIpnsName,
        });

        if (storedVault.teeKeys) {
          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
        }

        setVaultKeys({
          rootFolderKey: newVault.rootFolderKey,
          rootIpnsKeypair: newVault.rootIpnsKeypair,
          rootIpnsName,
          vaultId: storedVault.id,
          isNewVault: true,
        });
      } else {
        console.error('[useAuth] Failed to load vault:', error);
        throw error;
      }
    }

    // Non-blocking device registry initialization (fire-and-forget)
    // Placed after vault load so registry failures never block login
    void (async () => {
      try {
        const deviceKeypair = await getOrCreateDeviceIdentity(userKeypair.privateKey);
        const deviceInfo = detectDeviceInfo();
        const result = await initializeOrSyncRegistry({
          userPrivateKey: userKeypair.privateKey,
          userPublicKey: userKeypair.publicKey,
          deviceKeypair,
          deviceInfo: { ...deviceInfo, ipHash: '' },
        });
        if (result) {
          useDeviceRegistryStore
            .getState()
            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
        }
      } catch (error) {
        console.error('[Auth] Device registry init failed (non-blocking):', error);
      }
    })();

    // Non-blocking bin initialization (fire-and-forget)
    void (async () => {
      try {
        await initializeBin({
          userPrivateKey: userKeypair.privateKey,
          userPublicKey: userKeypair.publicKey,
        });
      } catch (error) {
        console.error('[Auth] Bin initialization failed (non-blocking):', error);
      }
    })();

    // Non-blocking: fetch retention config from API
    void (async () => {
      try {
        const config = await vaultControllerGetConfig();
        if (config.recycleBinRetentionDays != null) {
          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
        }
      } catch (error) {
        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
      }
    })();
  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);

  /**
   * Complete backend authentication after Core Kit login.
   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
   * to the backend with loginType 'corekit'. The backend verifies it against
   * its own JWKS since CipherBox is the identity provider.
   */
  const completeBackendAuth = useCallback(
    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
      // 1. Get real publicKey from Core Kit TSS export
      const publicKey = await getPublicKeyHex();
      if (!publicKey) {
        throw new Error('Failed to get publicKey from Core Kit');
      }

      // publicKey available for debugging via DevTools if needed

      // 2. Authenticate with CipherBox backend
      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
      const response = await authApi.login({
        idToken: cipherboxJwt,
        publicKey,
        loginType: 'corekit',
      });

      // 3. Store access token (refresh token in HTTP-only cookie)
      setAccessToken(response.accessToken);

      // 4. Remember auth method for UX
      setLastAuthMethod(authMethod);

      // 5. Initialize or load vault
      await initializeOrLoadVault();
    },
    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
  );

  /**
   * Complete the login flow after REQUIRED_SHARE is resolved.
   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
   * (since Core Kit is now LOGGED_IN), then navigates to /files.
   */
  const completeRequiredShare = useCallback(async (): Promise<void> => {
    // Read directly from Zustand store to get fresh values — this callback
    // may be called from useDeviceApproval's useAuth() instance, so we
    // can't rely on closure-captured selector values.
    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();

    if (!jwt || !method) {
      throw new Error('No pending auth info for REQUIRED_SHARE completion');
    }

    // Core Kit should now be LOGGED_IN after inputFactorKey()
    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
    await completeBackendAuth(method, jwt);

    // NOW sync Core Kit React state to LOGGED_IN.
    // We deliberately delayed this from inputFactorKey() to prevent the session
    // restoration effect from firing before backend auth completed.
    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
    syncStatus();

    // Clear pending state
    setPendingAuth(null, null);

    // Navigate to files
    navigate('/files');
  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);

  /**
   * Login with Google OAuth token.
   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
   */
  const loginWithGoogle = useCallback(
    async (googleIdToken: string): Promise<void> => {
      if (isLoggingIn) return;
      setIsLoggingIn(true);
      try {
        // 1. Core Kit login via CipherBox identity provider
        const {
          cipherboxJwt,
          email,
          userId,
          status: coreKitStatus,
        } = await coreKitLoginGoogle(googleIdToken);

        if (coreKitStatus === 'required_share') {
          // MFA enabled but device factor missing.
          // Store pending auth info for later completion after factor input.
          setPendingAuth(cipherboxJwt, 'google');

          // Obtain temporary backend access token so the new device can
          // call bulletin board API endpoints (device-approval/*).
          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
          // state and we can't export the TSS key yet.
          const tempLoginResponse = await authApi.login({
            idToken: cipherboxJwt,
            publicKey: `pending-core-kit-${userId}`,
            loginType: 'corekit',
          });
          setAccessToken(tempLoginResponse.accessToken);

          if (email) {
            setUserEmail(email);
          }

          // Do NOT call completeBackendAuth() or navigate('/files')
          // The component tree will see isRequiredShare === true and
          // render recovery/approval UI.
          return;
        }

        // Normal path: Core Kit logged in, proceed as before
        // 2. Complete backend auth + vault init
        await completeBackendAuth('google', cipherboxJwt);

        // 3. Store email for UI display (returned from identity endpoint)
        if (email) {
          setUserEmail(email);
        }

        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
      } catch (error) {
        console.error('[useAuth] Google login failed:', error);
        throw error;
      } finally {
        setIsLoggingIn(false);
      }
    },
    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
  );

  /**
   * Login with Email OTP.
   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
   */
  const loginWithEmail = useCallback(
    async (email: string, otp: string): Promise<void> => {
      if (isLoggingIn) return;
      setIsLoggingIn(true);
      try {
        // 1. Core Kit login via CipherBox identity provider
        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);

        if (coreKitStatus === 'required_share') {
          setPendingAuth(cipherboxJwt, 'email');

          const tempLoginResponse = await authApi.login({
            idToken: cipherboxJwt,
            publicKey: `pending-core-kit-${userId}`,
            loginType: 'corekit',
          });
          setAccessToken(tempLoginResponse.accessToken);
          setUserEmail(email);
          return;
        }

        // Normal path
        await completeBackendAuth('email', cipherboxJwt);
        setUserEmail(email);
        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
      } catch (error) {
        console.error('[useAuth] Email login failed:', error);
        throw error;
      } finally {
        setIsLoggingIn(false);
      }
    },
    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
  );

  /**
   * Login with Wallet (SIWE).
   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
   */
  const loginWithWallet = useCallback(
    async (cipherboxJwt: string, userId: string): Promise<void> => {
      if (isLoggingIn) return;
      setIsLoggingIn(true);
      try {
        // 1. Core Kit login via CipherBox identity provider
        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);

        if (coreKitStatus === 'required_share') {
          setPendingAuth(cipherboxJwt, 'wallet');

          const tempLoginResponse = await authApi.login({
            idToken: cipherboxJwt,
            publicKey: `pending-core-kit-${userId}`,
            loginType: 'corekit',
          });
          setAccessToken(tempLoginResponse.accessToken);
          return;
        }

        // Normal path
        await completeBackendAuth('wallet', cipherboxJwt);
        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
        // inside it may still be pending. An explicit navigate here would fire AFTER
        // vault init completes — by which point the user may have navigated away from
        // the login page, causing a disruptive late redirect.
      } catch (error) {
        console.error('[useAuth] Wallet login failed:', error);
        throw error;
      } finally {
        setIsLoggingIn(false);
      }
    },
    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
  );

  /**
   * Legacy login() for backward compatibility with AuthButton.
   * With Core Kit, login requires specifying the auth method.
   * This will be replaced by the new Login UI in Plan 04.
   */
  const login = useCallback(async () => {
    // Plan 04 will build the new login UI with method selection.
    // For now, this is a no-op placeholder that AuthButton calls.
    console.warn(
      '[useAuth] login() called without method -- ' +
        'use loginWithGoogle() or loginWithEmail() instead. ' +
        'Plan 04 will provide the new Login UI.'
    );
  }, []);

  // Complete logout: Backend -> Core Kit -> Clear state
  const logout = useCallback(async () => {
    if (isLoggingOut) return;

    setIsLoggingOut(true);
    try {
      // 1. Call backend logout (clears cookie)
      if (accessToken) {
        try {
          await authApi.logout();
        } catch {
          // Ignore errors -- we'll clear state anyway
        }
      }

      // 2. Logout Core Kit (clears session from localStorage)
      await coreKitLogout();

      // 3. Clear all user-scoped stores (centralized helper)
      clearAllUserStores();

      // 4. Navigate to login
      navigate('/');
    } catch (error) {
      console.error('[useAuth] Logout failed:', error);
      // Still clear state even if backend fails
      clearAllUserStores();
      navigate('/');
    } finally {
      setIsLoggingOut(false);
    }
  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);

  // Keep function refs up-to-date for use in session restoration effect.
  // Using refs prevents the effect from re-firing when function identities change.
  initializeOrLoadVaultRef.current = initializeOrLoadVault;
  coreKitLogoutRef.current = coreKitLogout;

  // Session restoration: if Core Kit restores a session from localStorage
  // on init, we have LOGGED_IN status without going through login flow.
  // Complete backend auth + vault loading.
  useEffect(() => {
    const restoreSession = async () => {
      // Only restore if Core Kit has a session but we don't have
      // a backend access token yet
      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
        restoringRef.current = true;
        setIsLoggingIn(true);
        try {
          // Try to refresh using the HTTP-only cookie first
          const response = await authApi.refresh();
          setAccessToken(response.accessToken);

          // Restore email from backend if available
          if (response.email) {
            setUserEmail(response.email);
          }

          // Load vault keys from Core Kit keypair
          await initializeOrLoadVaultRef.current?.();
        } catch {
          // No valid backend session -- user needs to re-login
          // Core Kit session exists but backend cookie expired
          // Clear Core Kit session to avoid inconsistent state
          try {
            await coreKitLogoutRef.current?.();
          } catch {
            // Ignore logout errors during cleanup
          }
        } finally {
          restoringRef.current = false;
          setIsLoggingIn(false);
        }
      }
    };
    restoreSession();
  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);

  return {
    isLoading,
    isAuthenticated,
    isRequiredShare,
    lastAuthMethod,
    userEmail,
    pendingAuthMethod,
    login,
    loginWithGoogle,
    loginWithEmail,
    loginWithWallet,
    completeRequiredShare,
    logout,
  };
}

/**
 * useDeviceApproval Hook
 *
 * Manages the full lifecycle for BOTH sides of the cross-device approval flow:
 *
 * **New device (requester):**
 * - Generate ephemeral secp256k1 keypair
 * - Create bulletin board request
 * - Poll for approval status
 * - On approval: ECIES-decrypt factor key, inputFactorKey, create device factor
 *
 * **Existing device (approver):**
 * - Poll for pending approval requests
 * - Approve: ECIES-encrypt current factor key with requester's ephemeral public key
 * - Deny: mark request as denied
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import * as secp256k1 from '@noble/secp256k1';
import {
  generateFactorKey,
  TssShareType,
  FactorKeyTypeShareDescription,
} from '@web3auth/mpc-core-kit';
import { wrapKey, unwrapKey, hexToBytes, bytesToHex } from '@cipherbox/crypto';
import { useCoreKit } from '../lib/web3auth/core-kit-provider';
import { useMfa } from './useMfa';
import { useVisibility } from './useVisibility';
import { useAuth } from './useAuth';
import { useAuthStore } from '../stores/auth.store';
import { getOrCreateDeviceIdentity } from '../lib/device/identity';
import { detectDeviceInfo } from '../lib/device/info';
import {
  deviceApprovalApi,
  type ApprovalStatusResponse,
  type PendingApproval,
} from '../services/device-approval.service';

export type ApprovalStatus =
  | 'idle'
  | 'requesting'
  | 'pending'
  | 'approved'
  | 'denied'
  | 'expired'
  | 'completing'
  | 'error';

export function useDeviceApproval() {
  const { coreKit } = useCoreKit();
  const { inputFactorKey } = useMfa();
  const { completeRequiredShare } = useAuth();
  const isVisible = useVisibility();

  // --- New device (requester) state ---
  const [approvalStatus, setApprovalStatus] = useState<ApprovalStatus>('idle');
  const [approvalError, setApprovalError] = useState<string | null>(null);
  const requestIdRef = useRef<string | null>(null);
  const ephemeralPrivKeyRef = useRef<Uint8Array | null>(null);
  // Generation counter to detect stale requestApproval completions.
  // In React StrictMode, the effect fires twice (mount→unmount→remount), launching
  // two concurrent requestApproval() calls whose async completions can race.
  // Each call increments the counter; after each await, the call checks if it's
  // still the active generation — if not, it cancels itself and returns early.
  const requestGenRef = useRef(0);
  const requesterPollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // --- Existing device (approver) state ---
  const [pendingRequests, setPendingRequests] = useState<PendingApproval[]>([]);
  const isPollingPendingRef = useRef(false);
  const approverPollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Track recently approved/denied request IDs to filter out stale polling responses.
  // Without this, the 5s polling interval can re-add a request that was just handled
  // if the poll response was already in-flight when the respond API call completed.
  const handledRequestIdsRef = useRef<Set<string>>(new Set());

  /**
   * Zero-fill and clear ephemeral private key from memory.
   */
  const clearEphemeralKey = useCallback(() => {
    if (ephemeralPrivKeyRef.current) {
      ephemeralPrivKeyRef.current.fill(0);
      ephemeralPrivKeyRef.current = null;
    }
  }, []);

  /**
   * Stop requester polling.
   */
  const stopRequesterPolling = useCallback(() => {
    if (requesterPollRef.current) {
      clearInterval(requesterPollRef.current);
      requesterPollRef.current = null;
    }
  }, []);

  /**
   * Stop approver polling.
   */
  const stopApproverPolling = useCallback(() => {
    if (approverPollRef.current) {
      clearInterval(approverPollRef.current);
      approverPollRef.current = null;
    }
    isPollingPendingRef.current = false;
    handledRequestIdsRef.current.clear();
  }, []);

  // =========================================================================
  // NEW DEVICE SIDE (REQUESTER)
  // =========================================================================

  /**
   * Handle a successful approval: decrypt factor key, input it, create device factor.
   */
  const handleApprovalSuccess = useCallback(
    async (encryptedFactorKeyHex: string) => {
      setApprovalStatus('completing');

      try {
        const ephPrivKey = ephemeralPrivKeyRef.current;
        if (!ephPrivKey) {
          throw new Error('Ephemeral private key not available');
        }
        if (!coreKit) {
          throw new Error('Core Kit not initialized');
        }

        // 1. ECIES-decrypt the factor key
        const encrypted = hexToBytes(encryptedFactorKeyHex);
        const factorKeyBytes = await unwrapKey(encrypted, ephPrivKey);
        const factorKeyHex = bytesToHex(factorKeyBytes);
        factorKeyBytes.fill(0); // Zero-fill decrypted key material after conversion

        // 2. Input the factor key to complete Core Kit login
        await inputFactorKey(factorKeyHex);

        // 3. Create device factor for this new device
        const newDeviceFactor = generateFactorKey();
        await coreKit.createFactor({
          shareType: TssShareType.DEVICE,
          factorKey: newDeviceFactor.private,
          shareDescription: FactorKeyTypeShareDescription.DeviceShare,
        });
        await coreKit.setDeviceFactor(newDeviceFactor.private);
        await coreKit.commitChanges();

        // 4. Clean up ephemeral key
        clearEphemeralKey();

        // 5. Complete the login flow
        await completeRequiredShare();

        setApprovalStatus('approved');
      } catch (err) {
        stopRequesterPolling();
        clearEphemeralKey();
        setApprovalError(err instanceof Error ? err.message : 'Failed to complete approval');
        setApprovalStatus('error');
      }
    },
    [coreKit, inputFactorKey, completeRequiredShare, clearEphemeralKey, stopRequesterPolling]
  );

  /**
   * Start polling for approval status (new device side).
   */
  const startRequesterPolling = useCallback(
    (requestId: string) => {
      stopRequesterPolling();

      const poll = async () => {
        // Separate network fetch from success handling so network errors
        // don't swallow failures from handleApprovalSuccess/completeRequiredShare
        let result: ApprovalStatusResponse;
        try {
          result = await deviceApprovalApi.getStatus(requestId);
        } catch {
          // Network error -- continue polling, don't crash
          return;
        }

        if (result.status === 'approved' && result.encryptedFactorKey) {
          stopRequesterPolling();
          await handleApprovalSuccess(result.encryptedFactorKey);
        } else if (result.status === 'denied') {
          stopRequesterPolling();
          clearEphemeralKey();
          setApprovalStatus('denied');
        } else if (result.status === 'expired') {
          stopRequesterPolling();
          clearEphemeralKey();
          setApprovalStatus('expired');
        }
        // 'pending' -> continue polling
      };

      requesterPollRef.current = setInterval(poll, 3000);
      // Fire immediately
      void poll();
    },
    [stopRequesterPolling, handleApprovalSuccess, clearEphemeralKey]
  );

  /**
   * Create an approval request on the bulletin board (new device side).
   * Generates an ephemeral keypair and starts polling.
   *
   * Uses a generation counter to handle React StrictMode double-mounting:
   * the effect fires requestApproval twice in quick succession. Without the
   * counter, both async calls race to set requestIdRef and start polling.
   * If the first call's createRequest completes after the second's, it
   * overwrites the ref and starts polling for a stale request (whose
   * ephemeral key was already zeroed by cleanup), causing "Key unwrapping
   * failed" when the approver encrypts the factor key with the stale
   * request's public key.
   */
  const requestApproval = useCallback(async () => {
    const gen = ++requestGenRef.current;

    setApprovalStatus('requesting');
    setApprovalError(null);

    try {
      // 1. Generate ephemeral secp256k1 keypair
      // keygen() returns compressed pubkey (33 bytes) by default, but the
      // backend DTO requires uncompressed (65 bytes = 130 hex chars).
      const ephemeral = secp256k1.keygen();
      ephemeralPrivKeyRef.current = ephemeral.secretKey;
      const uncompressedPubKey = secp256k1.getPublicKey(ephemeral.secretKey, false);
      const ephemeralPubKeyHex = bytesToHex(uncompressedPubKey);

      // 2. Get device identity
      const deviceIdentity = await getOrCreateDeviceIdentity();

      // 3. Get device name
      const deviceInfo = detectDeviceInfo();

      // 4. Create request on bulletin board
      const { requestId } = await deviceApprovalApi.createRequest({
        deviceId: deviceIdentity.deviceId,
        deviceName: deviceInfo.name,
        ephemeralPublicKey: ephemeralPubKeyHex,
      });

      // 5. Check if this call was superseded by a newer requestApproval()
      //    (happens in React StrictMode when the effect fires twice).
      if (gen !== requestGenRef.current) {
        // Stale: a newer requestApproval already started. Cancel this request
        // on the backend and bail — the newer call will set its own refs.
        try {
          await deviceApprovalApi.cancel(requestId);
        } catch {
          /* best-effort */
        }
        return;
      }

      requestIdRef.current = requestId;
      setApprovalStatus('pending');

      // 6. Start polling for response
      startRequesterPolling(requestId);
    } catch (err) {
      // Only handle errors for the active generation
      if (gen !== requestGenRef.current) return;
      clearEphemeralKey();
      setApprovalError(err instanceof Error ? err.message : 'Failed to create approval request');
      setApprovalStatus('error');
    }
  }, [startRequesterPolling, clearEphemeralKey]);

  /**
   * Cancel the pending approval request (new device side).
   * Also called when recovery phrase is used instead (RESEARCH.md Pitfall 5).
   *
   * IMPORTANT: All synchronous state cleanup (stop polling, clear ephemeral key,
   * null refs, reset status) MUST happen BEFORE the async API call. In React
   * StrictMode, cleanup and setup run in quick succession — if requestApproval()
   * generates a new ephemeral key between our `await cancel()` and
   * `clearEphemeralKey()`, we'd zero the NEW key, causing "Key unwrapping failed"
   * when the approve response arrives.
   */
  const cancelRequest = useCallback(async () => {
    // Invalidate any in-flight requestApproval() completion immediately.
    requestGenRef.current += 1;

    stopRequesterPolling();
    clearEphemeralKey();
    setApprovalStatus('idle');

    // Capture and clear requestId synchronously so a concurrent
    // requestApproval() can safely set a new value on the ref.
    const requestId = requestIdRef.current;
    requestIdRef.current = null;

    // Async API cleanup (best-effort, uses captured local variable)
    if (requestId) {
      try {
        await deviceApprovalApi.cancel(requestId);
      } catch {
        // Best-effort cleanup -- request may already be expired/cancelled
      }
    }
  }, [stopRequesterPolling, clearEphemeralKey]);

  // =========================================================================
  // EXISTING DEVICE SIDE (APPROVER)
  // =========================================================================

  /**
   * Fetch pending requests from the bulletin board, filtering out recently
   * handled ones to prevent stale in-flight responses from re-adding them.
   */
  const fetchFilteredPending = useCallback(async () => {
    try {
      const pending = await deviceApprovalApi.getPending();
      // Guard against in-flight responses resolving after polling stopped
      if (!isPollingPendingRef.current) return;
      const handled = handledRequestIdsRef.current;
      const filtered =
        handled.size > 0
          ? pending.filter((r) => r.requestId && !handled.has(r.requestId))
