  // Each call increments the counter; after each await, the call checks if it's
  // still the active generation — if not, it cancels itself and returns early.
  const requestGenRef = useRef(0);
  const requesterPollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // --- Existing device (approver) state ---
  const [pendingRequests, setPendingRequests] = useState<PendingApproval[]>([]);
  const isPollingPendingRef = useRef(false);
  const approverPollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Track recently approved/denied request IDs to filter out stale polling responses.
  // Without this, the 5s polling interval can re-add a request that was just handled
  // if the poll response was already in-flight when the respond API call completed.
  const handledRequestIdsRef = useRef<Set<string>>(new Set());

  /**
   * Zero-fill and clear ephemeral private key from memory.
   */
  const clearEphemeralKey = useCallback(() => {
    if (ephemeralPrivKeyRef.current) {
      ephemeralPrivKeyRef.current.fill(0);
      ephemeralPrivKeyRef.current = null;
    }
  }, []);

  /**
   * Stop requester polling.
   */
  const stopRequesterPolling = useCallback(() => {
    if (requesterPollRef.current) {
      clearInterval(requesterPollRef.current);
      requesterPollRef.current = null;
    }
  }, []);

  /**
   * Stop approver polling.
   */
  const stopApproverPolling = useCallback(() => {
    if (approverPollRef.current) {
      clearInterval(approverPollRef.current);
      approverPollRef.current = null;
    }
    isPollingPendingRef.current = false;
    handledRequestIdsRef.current.clear();
  }, []);

  // =========================================================================
  // NEW DEVICE SIDE (REQUESTER)
  // =========================================================================

  /**
   * Handle a successful approval: decrypt factor key, input it, create device factor.
   */
  const handleApprovalSuccess = useCallback(
    async (encryptedFactorKeyHex: string) => {
      setApprovalStatus('completing');

      try {
        const ephPrivKey = ephemeralPrivKeyRef.current;
        if (!ephPrivKey) {
          throw new Error('Ephemeral private key not available');
        }
        if (!coreKit) {
          throw new Error('Core Kit not initialized');
        }

        // 1. ECIES-decrypt the factor key
        const encrypted = hexToBytes(encryptedFactorKeyHex);
        const factorKeyBytes = await unwrapKey(encrypted, ephPrivKey);
        const factorKeyHex = bytesToHex(factorKeyBytes);
        factorKeyBytes.fill(0); // Zero-fill decrypted key material after conversion

        // 2. Input the factor key to complete Core Kit login
        await inputFactorKey(factorKeyHex);

        // 3. Create device factor for this new device
        const newDeviceFactor = generateFactorKey();
        await coreKit.createFactor({
          shareType: TssShareType.DEVICE,
          factorKey: newDeviceFactor.private,
          shareDescription: FactorKeyTypeShareDescription.DeviceShare,
        });
        await coreKit.setDeviceFactor(newDeviceFactor.private);
        await coreKit.commitChanges();

        // 4. Clean up ephemeral key
        clearEphemeralKey();

        // 5. Complete the login flow
        await completeRequiredShare();

        setApprovalStatus('approved');
      } catch (err) {
        stopRequesterPolling();
        clearEphemeralKey();
        setApprovalError(err instanceof Error ? err.message : 'Failed to complete approval');
        setApprovalStatus('error');
      }
    },
    [coreKit, inputFactorKey, completeRequiredShare, clearEphemeralKey, stopRequesterPolling]
  );

  /**
   * Start polling for approval status (new device side).
   */
  const startRequesterPolling = useCallback(
    (requestId: string) => {
      stopRequesterPolling();

      const poll = async () => {
        // Separate network fetch from success handling so network errors
        // don't swallow failures from handleApprovalSuccess/completeRequiredShare
        let result: ApprovalStatusResponse;
        try {
          result = await deviceApprovalApi.getStatus(requestId);
        } catch {
          // Network error -- continue polling, don't crash
          return;
        }

        if (result.status === 'approved' && result.encryptedFactorKey) {
          stopRequesterPolling();
          await handleApprovalSuccess(result.encryptedFactorKey);
        } else if (result.status === 'denied') {
          stopRequesterPolling();
          clearEphemeralKey();
          setApprovalStatus('denied');
        } else if (result.status === 'expired') {
          stopRequesterPolling();
          clearEphemeralKey();
          setApprovalStatus('expired');
        }
        // 'pending' -> continue polling
      };

      requesterPollRef.current = setInterval(poll, 3000);
      // Fire immediately
      void poll();
    },
    [stopRequesterPolling, handleApprovalSuccess, clearEphemeralKey]
  );

  /**
   * Create an approval request on the bulletin board (new device side).
   * Generates an ephemeral keypair and starts polling.
   *
   * Uses a generation counter to handle React StrictMode double-mounting:
   * the effect fires requestApproval twice in quick succession. Without the
   * counter, both async calls race to set requestIdRef and start polling.
   * If the first call's createRequest completes after the second's, it
   * overwrites the ref and starts polling for a stale request (whose
   * ephemeral key was already zeroed by cleanup), causing "Key unwrapping
   * failed" when the approver encrypts the factor key with the stale
   * request's public key.
   */
  const requestApproval = useCallback(async () => {
    const gen = ++requestGenRef.current;

    setApprovalStatus('requesting');
    setApprovalError(null);

    try {
      // 1. Generate ephemeral secp256k1 keypair
      // keygen() returns compressed pubkey (33 bytes) by default, but the
      // backend DTO requires uncompressed (65 bytes = 130 hex chars).
      const ephemeral = secp256k1.keygen();
      ephemeralPrivKeyRef.current = ephemeral.secretKey;
      const uncompressedPubKey = secp256k1.getPublicKey(ephemeral.secretKey, false);
      const ephemeralPubKeyHex = bytesToHex(uncompressedPubKey);

      // 2. Get device identity
      const deviceIdentity = await getOrCreateDeviceIdentity({ mode: 'ephemeral' });

      // 3. Get device name
      const deviceInfo = detectDeviceInfo();

      // 4. Create request on bulletin board
      const { requestId } = await deviceApprovalApi.createRequest({
        deviceId: deviceIdentity.deviceId,
        deviceName: deviceInfo.name,
        ephemeralPublicKey: ephemeralPubKeyHex,
      });

      // 5. Check if this call was superseded by a newer requestApproval()
      //    (happens in React StrictMode when the effect fires twice).
      if (gen !== requestGenRef.current) {
        // Stale: a newer requestApproval already started. Cancel this request
        // on the backend and bail — the newer call will set its own refs.
        try {
          await deviceApprovalApi.cancel(requestId);
        } catch {
          /* best-effort */
        }
        return;
      }

      requestIdRef.current = requestId;
      setApprovalStatus('pending');

      // 6. Start polling for response
      startRequesterPolling(requestId);
    } catch (err) {
      // Only handle errors for the active generation
      if (gen !== requestGenRef.current) return;
      clearEphemeralKey();
      setApprovalError(err instanceof Error ? err.message : 'Failed to create approval request');
      setApprovalStatus('error');
    }
  }, [startRequesterPolling, clearEphemeralKey]);

  /**
   * Cancel the pending approval request (new device side).
   * Also called when recovery phrase is used instead (RESEARCH.md Pitfall 5).
   *
   * IMPORTANT: All synchronous state cleanup (stop polling, clear ephemeral key,
   * null refs, reset status) MUST happen BEFORE the async API call. In React
   * StrictMode, cleanup and setup run in quick succession — if requestApproval()
   * generates a new ephemeral key between our `await cancel()` and
   * `clearEphemeralKey()`, we'd zero the NEW key, causing "Key unwrapping failed"
   * when the approve response arrives.
   */
  const cancelRequest = useCallback(async () => {
    // Invalidate any in-flight requestApproval() completion immediately.
    requestGenRef.current += 1;

    stopRequesterPolling();
    clearEphemeralKey();
    setApprovalStatus('idle');

    // Capture and clear requestId synchronously so a concurrent
    // requestApproval() can safely set a new value on the ref.
    const requestId = requestIdRef.current;
    requestIdRef.current = null;

    // Async API cleanup (best-effort, uses captured local variable)
    if (requestId) {
      try {
        await deviceApprovalApi.cancel(requestId);
      } catch {
        // Best-effort cleanup -- request may already be expired/cancelled
      }
    }
  }, [stopRequesterPolling, clearEphemeralKey]);

  // =========================================================================
  // EXISTING DEVICE SIDE (APPROVER)
  // =========================================================================

  /**
   * Fetch pending requests from the bulletin board, filtering out recently
   * handled ones to prevent stale in-flight responses from re-adding them.
   */
  const fetchFilteredPending = useCallback(async () => {
    try {
      const pending = await deviceApprovalApi.getPending();
      // Guard against in-flight responses resolving after polling stopped
      if (!isPollingPendingRef.current) return;
      const handled = handledRequestIdsRef.current;
      const filtered =
        handled.size > 0
          ? pending.filter((r) => r.requestId && !handled.has(r.requestId))
          : pending;
      setPendingRequests(filtered);
    } catch {
      // Network error -- continue polling
    }
  }, []);

  /**
   * Start polling for pending approval requests (existing device side).
   */
  const pollPendingRequests = useCallback(() => {
    if (isPollingPendingRef.current) return;
    isPollingPendingRef.current = true;

    // Poll every 5 seconds
    approverPollRef.current = setInterval(fetchFilteredPending, 5000);
    // Fire immediately
    void fetchFilteredPending();
  }, [fetchFilteredPending]);

  /**
   * Approve a pending request: ECIES-encrypt current factor key with
   * the requester's ephemeral public key and send the response.
   */
  const approveRequest = useCallback(
    async (requestId: string, ephemeralPublicKeyHex: string) => {
      if (!coreKit) throw new Error('Core Kit not initialized');

      // 1. Get current factor key
      const factorKeyResult = coreKit.getCurrentFactorKey();
      if (!factorKeyResult?.factorKey) {
        throw new Error('No active factor key available to share');
      }
      const factorKeyHex = factorKeyResult.factorKey.toString('hex').padStart(64, '0');
      const factorKeyBytes = hexToBytes(factorKeyHex);

      // 2. ECIES-encrypt with the requester's ephemeral public key
      const ephemeralPubKey = hexToBytes(ephemeralPublicKeyHex);
      const encrypted = await wrapKey(factorKeyBytes, ephemeralPubKey);
      factorKeyBytes.fill(0); // Zero-fill factor key bytes after wrapping

      // 3. Get current device ID for tracking
      const vaultPrivateKey = useAuthStore.getState().vaultKeypair?.privateKey;
      if (!vaultPrivateKey) {
        throw new Error('Vault keypair unavailable; cannot approve device request');
      }
      const deviceIdentity = await getOrCreateDeviceIdentity({ mode: 'persisted', vaultPrivateKey });

      // 4. Send response
      await deviceApprovalApi.respond(requestId, {
        action: 'approve',
        encryptedFactorKey: bytesToHex(encrypted),
        respondedByDeviceId: deviceIdentity.deviceId,
      });

      // 5. Remove from pending list and mark as handled to prevent
      //    stale polling responses from re-adding it
      handledRequestIdsRef.current.add(requestId);
      setPendingRequests((prev) => prev.filter((r) => r.requestId !== requestId));
    },
    [coreKit]
  );

  /**
   * Deny a pending approval request.
   */
  const denyRequest = useCallback(async (requestId: string) => {
    // Get current device ID for tracking
    const vaultPrivateKey = useAuthStore.getState().vaultKeypair?.privateKey;
    if (!vaultPrivateKey) {
      throw new Error('Vault keypair unavailable; cannot deny device request');
    }
    const deviceIdentity = await getOrCreateDeviceIdentity(vaultPrivateKey);

    await deviceApprovalApi.respond(requestId, {
      action: 'deny',
      respondedByDeviceId: deviceIdentity.deviceId,
    });

    // Remove from pending list and mark as handled
    handledRequestIdsRef.current.add(requestId);
    setPendingRequests((prev) => prev.filter((r) => r.requestId !== requestId));
  }, []);

  // =========================================================================
  // VISIBILITY-BASED POLLING CONTROL (approver)
  // =========================================================================

  // Pause/resume approver polling based on tab visibility
  useEffect(() => {
    if (!isPollingPendingRef.current) return;

    if (isVisible) {
      // Resume polling when tab becomes visible
      if (!approverPollRef.current) {
        approverPollRef.current = setInterval(fetchFilteredPending, 5000);
        void fetchFilteredPending();
      }
    } else {
      // Pause polling when tab is hidden
      if (approverPollRef.current) {
        clearInterval(approverPollRef.current);
        approverPollRef.current = null;
      }
    }
  }, [isVisible, fetchFilteredPending]);

  // =========================================================================
  // CLEANUP ON UNMOUNT
  // =========================================================================

  useEffect(() => {
    return () => {
      stopRequesterPolling();
      stopApproverPolling();
      clearEphemeralKey();
    };
  }, [stopRequesterPolling, stopApproverPolling, clearEphemeralKey]);

  return {
    // Requester (new device)
    requestApproval,
    cancelRequest,
    approvalStatus,
    approvalError,

    // Approver (existing device)
    pollPendingRequests,
    stopApproverPolling,
    approveRequest,
    denyRequest,
    pendingRequests,
    isPolling: isPollingPendingRef.current,
  };
}

import { useCallback } from 'react';
import {
  COREKIT_STATUS,
  generateFactorKey,
  keyToMnemonic,
  mnemonicToKey,
  TssShareType,
  FactorKeyTypeShareDescription,
  factorKeyCurve,
} from '@web3auth/mpc-core-kit';
import { Point } from '@tkey/common-types';
import BN from 'bn.js';
import { useCoreKit } from '../lib/web3auth/core-kit-provider';
import { useMfaStore } from '../stores/mfa.store';
import { getOrCreateDeviceIdentity } from '../lib/device/identity';
import { detectDeviceInfo } from '../lib/device/info';

export type FactorInfo = {
  factorPubHex: string;
  description: string;
  type: string;
  /** Additional metadata set during createFactor (e.g. deviceId, browserName) */
  additionalMetadata?: Record<string, string>;
};

export function useMfa() {
  const { coreKit } = useCoreKit();

  const isMfaEnabled = useMfaStore((s) => s.isMfaEnabled);
  const isEnrolling = useMfaStore((s) => s.isEnrolling);
  const factorCount = useMfaStore((s) => s.factorCount);
  const threshold = useMfaStore((s) => s.threshold);

  /**
   * Check MFA status from Core Kit key details.
   * MFA is enabled when totalFactors > 2 (every account starts with 2
   * default factors: JWT verifier share + hashedShare cloud custodial key).
   */
  const checkMfaStatus = useCallback((): {
    isMfaEnabled: boolean;
    totalFactors: number;
    threshold: number;
  } => {
    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
    }
    try {
      const details = coreKit.getKeyDetails();
      const enabled = details.totalFactors > 2;
      useMfaStore.getState().setMfaEnabled(enabled);
      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
      return {
        isMfaEnabled: enabled,
        totalFactors: details.totalFactors,
        threshold: details.threshold,
      };
    } catch {
      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
    }
  }, [coreKit]);

  /**
   * Enable MFA. Returns 24-word recovery mnemonic.
   * CRITICAL: commitChanges() must be called before enableMFA() in manualSync mode.
   */
  const enableMfa = useCallback(async (): Promise<string> => {
    if (!coreKit) throw new Error('Core Kit not initialized');
    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
      throw new Error('Must be logged in to enable MFA');
    }

    const store = useMfaStore.getState();
    if (store.isMfaEnabled) {
      throw new Error('MFA is already enabled');
    }

    useMfaStore.getState().setEnrolling(true);
    try {
      // Commit any pending changes first (CRITICAL for manualSync mode -- Pitfall 1)
      await coreKit.commitChanges();

      // Capture TSS public key BEFORE enableMFA for stability verification (MFA-04)
      const preMfaTssPub = coreKit.getKeyDetails().tssPubKey;

      // enableMFA creates device factor + recovery factor atomically
      const backupFactorKeyHex = await coreKit.enableMFA({
        shareDescription: FactorKeyTypeShareDescription.SeedPhrase,
      });

      // Commit the MFA changes
      await coreKit.commitChanges();

      // Defensive check: verify TSS public key unchanged after MFA enrollment (MFA-04)
      const postMfaTssPub = coreKit.getKeyDetails().tssPubKey;
      if (preMfaTssPub?.x && preMfaTssPub?.y && postMfaTssPub?.x && postMfaTssPub?.y) {
        const preX = preMfaTssPub.x.toString('hex');
        const preY = preMfaTssPub.y.toString('hex');
        const postX = postMfaTssPub.x.toString('hex');
        const postY = postMfaTssPub.y.toString('hex');
        if (preX !== postX || preY !== postY) {
          throw new Error(
            'MFA enrollment failed: TSS public key changed. Your keypair identity is no longer stable. Please contact support.'
          );
        }
      }

      // Convert to 24-word mnemonic for user display
      const mnemonic = keyToMnemonic(backupFactorKeyHex);

      // Update store with new key details
      const details = coreKit.getKeyDetails();
      useMfaStore.getState().setMfaEnabled(true);
      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);

      return mnemonic;
    } finally {
      useMfaStore.getState().setEnrolling(false);
    }
  }, [coreKit]);

  /**
   * Input a factor key (hex string) to complete REQUIRED_SHARE login.
   * Used for both recovery and cross-device approval flows.
   *
   * IMPORTANT: Does NOT call syncStatus() because doing so would transition
   * Core Kit's React context to LOGGED_IN, which triggers the session
   * restoration effect in useAuth.ts. Since backend auth hasn't completed yet
   * (no valid access token or refresh cookie), the session restore fails and
   * calls coreKitLogout(), effectively undoing the recovery.
   *
   * The caller (completeRequiredShare) is responsible for syncing status
   * AFTER backend auth completes.
   */
  const inputFactorKey = useCallback(
    async (factorKeyHex: string): Promise<void> => {
      if (!coreKit) throw new Error('Core Kit not initialized');
      const factorKey = new BN(factorKeyHex, 'hex');
      await coreKit.inputFactorKey(factorKey);
      // syncStatus() deliberately omitted — see comment above
    },
    [coreKit]
  );

  /**
   * Recover with a 24-word mnemonic phrase.
   * After recovery, creates a device factor for the new device.
   */
  const recoverWithMnemonic = useCallback(
    async (mnemonic: string): Promise<void> => {
      if (!coreKit) throw new Error('Core Kit not initialized');

      // Convert mnemonic to factor key hex
      const factorKeyHex = mnemonicToKey(mnemonic.trim().toLowerCase());
      await inputFactorKey(factorKeyHex);

      // Create a device factor for this new device with metadata
      const newDeviceFactor = generateFactorKey();
      const deviceKeypair = await getOrCreateDeviceIdentity();
      const deviceInfo = detectDeviceInfo();
      await coreKit.createFactor({
        shareType: TssShareType.DEVICE,
        factorKey: newDeviceFactor.private,
        shareDescription: FactorKeyTypeShareDescription.DeviceShare,
        additionalMetadata: {
          deviceId: deviceKeypair.deviceId,
          browserName: deviceInfo.name,
        },
      });
      await coreKit.setDeviceFactor(newDeviceFactor.private);
      await coreKit.commitChanges();
    },
    [coreKit, inputFactorKey]
  );

  /**
   * Get all factors with their descriptions.
   * shareDescriptions is Record<string, string[]> where keys are factor pub hex.
   */
  const getFactors = useCallback((): FactorInfo[] => {
    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return [];
    try {
      const details = coreKit.getKeyDetails();
      const factors: FactorInfo[] = [];

      // Known system fields stored by Web3Auth in the flat JSON description.
      // Everything else is user-provided additionalMetadata (spread at top level by addFactorDescription).
      const systemFields = new Set(['module', 'dateAdded', 'tssShareIndex', 'tssIndex']);

      for (const [factorPubHex, descriptions] of Object.entries(details.shareDescriptions)) {
        for (const descJson of descriptions) {
          try {
            const parsed = JSON.parse(descJson) as Record<string, unknown>;
            const module = (parsed.module as string) || 'unknown';
            const tssShareIndex = parsed.tssShareIndex as number | undefined;

            // Normalize type: enableMFA() creates factors with module="Other"
            // but tssShareIndex correctly identifies 2=DEVICE, 3=RECOVERY
            let type = module;
            if (module === FactorKeyTypeShareDescription.Other || module === 'Other') {
              if (tssShareIndex === 2) {
                type = FactorKeyTypeShareDescription.DeviceShare;
              } else if (tssShareIndex === 3) {
                type = FactorKeyTypeShareDescription.SeedPhrase;
              }
            }

            // Extract additionalMetadata from flat JSON (Web3Auth spreads it at top level)
            const additionalMetadata: Record<string, string> = {};
            for (const [key, value] of Object.entries(parsed)) {
              if (!systemFields.has(key) && typeof value === 'string') {
                additionalMetadata[key] = value;
              }
            }

            factors.push({
              factorPubHex,
              description: type,
              type,
              additionalMetadata:
                Object.keys(additionalMetadata).length > 0 ? additionalMetadata : undefined,
            });
          } catch {
            factors.push({
              factorPubHex,
              description: 'unknown',
              type: 'unknown',
            });
          }
        }
      }

      return factors;
    } catch {
      return [];
    }
  }, [coreKit]);

  /**
   * Delete a factor by its public key hex.
   * Cannot delete the currently active factor or the last remaining factor.
   */
  const deleteFactor = useCallback(
    async (factorPubHex: string): Promise<void> => {
      if (!coreKit) throw new Error('Core Kit not initialized');
      const factorPub = Point.fromSEC1(factorKeyCurve, factorPubHex);
      await coreKit.deleteFactor(factorPub);
      await coreKit.commitChanges();
    },
    [coreKit]
  );

  /**
   * Get the current active factor key and share type.
   */
  const getCurrentFactorKey = useCallback((): {
    factorKey: BN;
    shareType: TssShareType;
  } | null => {
    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
    try {
      return coreKit.getCurrentFactorKey();
    } catch {
      return null;
    }
  }, [coreKit]);

  /**
   * Regenerate the recovery phrase.
   * Deletes the old recovery factor and creates a new one.
   * Returns the new 24-word mnemonic.
   */
  const regenerateRecoveryPhrase = useCallback(async (): Promise<string> => {
    if (!coreKit) throw new Error('Core Kit not initialized');
    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
      throw new Error('Must be logged in to regenerate recovery phrase');
    }

    // Find the existing recovery (seedPhrase) factor
    const factors = getFactors();
    const recoveryFactor = factors.find((f) => f.type === FactorKeyTypeShareDescription.SeedPhrase);

    if (recoveryFactor) {
      // Delete old recovery factor
      const factorPub = Point.fromSEC1(factorKeyCurve, recoveryFactor.factorPubHex);
      await coreKit.deleteFactor(factorPub);
    }

    // Generate new recovery factor
    const newRecovery = generateFactorKey();
    await coreKit.createFactor({
      shareType: TssShareType.RECOVERY,
      factorKey: newRecovery.private,
      shareDescription: FactorKeyTypeShareDescription.SeedPhrase,
    });
    await coreKit.commitChanges();

    // Convert the new factor key to mnemonic
    // Zero-pad to 64 hex chars (32 bytes)
    const factorKeyHex = newRecovery.private.toString('hex').padStart(64, '0');
    return keyToMnemonic(factorKeyHex);
  }, [coreKit, getFactors]);

  return {
    // State from store
    isMfaEnabled,
    isEnrolling,
    factorCount,
    threshold,

    // Operations
    checkMfaStatus,
    enableMfa,
    inputFactorKey,
    recoverWithMnemonic,
    getFactors,
    deleteFactor,
    getCurrentFactorKey,
    regenerateRecoveryPhrase,
  };
}
